"""Build a dependency-free portfolio from the original project notebooks."""
import base64
import html
import json
from pathlib import Path
from urllib.parse import quote

ROOT = Path(__file__).resolve().parent.parent
PROJECTS = [
    ('earnings-call-logs', 'Earning Call Logs.ipynb', 'Earnings Call Logs', 'Data collection', 'From financial conversations to structured data.', ['Python', 'BeautifulSoup', 'pandas'], 'Collect earnings call transcripts across ten listing pages, separate prepared remarks from Q&A, and organize both full calls and individual speaker turns into two dataframes.', 'The saved run collected 20 links on each of ten pages. Preview tables show company names, call dates, transcript text, and speaker turns labeled Prepared or QA. The code exports both dataframes to Excel.', 'An internet connection, requests, BeautifulSoup, pandas, an Excel writer, and a writable output folder. Update the Google Drive paths before running.'),
    ('mnist', 'MNIST.ipynb', 'Handwritten Digit Recognition', 'Machine learning', 'Teaching a neural network to read handwritten digits.', ['Python', 'NumPy', 'SciPy'], 'Build and train a neural network on MNIST, evaluate digit predictions, then test it on custom handwritten PNG images.', 'The saved MNIST evaluation reports 94.48% accuracy. Custom-image tests include both matches and mismatches, illustrating the gap between the benchmark and new handwriting. This is a recorded notebook result, not a new evaluation.', 'MNIST training and test CSV files, NumPy, SciPy, Matplotlib, Pillow, and your own digit PNGs. Update the dataset paths; training can take time.'),
    ('naive-bayes', 'Naiive Bayes.ipynb', 'Earnings Call Classifier', 'Machine learning', 'Distinguishing prepared remarks from Q&A with language.', ['Python', 'Naive Bayes', 'Gradio'], 'Build a Naive Bayes text classifier that accepts a sentence, predicts Prepared Remarks or Q&A Response, and displays the scores in a Gradio interface.', 'The saved dataset contains 11,401 speaker turns and a vocabulary of 44,894 words. The example “we expect strong revenue growth” is classified as Prepared Remarks, with scores of −27.43 and −30.72. The saved Gradio launch failed to create a share link; no public demo is claimed.', 'The earnings-call speaker-turn dataset, pandas, math, and Gradio. Update the input path, build the word dictionaries, and run the interface cells. No held-out accuracy is recorded.'),
    ('download-10ks', 'Download 100 10-Ks.ipynb', 'SEC 10-K Collection', 'Data collection', 'Building the starting point for financial text analysis.', ['Python', 'requests', 'SEC EDGAR'], 'Read a company index, select the first 100 matching 10-K filings while excluding 10-K/A amendments, and download the filing text with identifying metadata.', 'Saved output lists CIKs, filing dates, and SEC archive URLs, followed by word-frequency output. The notebook implements the download workflow; it does not include an independent download-success audit.', 'A company.idx file, requests, a writable download folder, and internet access. Update the paths and SEC User-Agent with your own valid research contact before running.'),
    ('sentiment-analysis', 'SentimentAnalysis.ipynb', 'Financial Sentiment Analysis', 'Text mining', 'Measuring the language inside annual reports.', ['Python', 'pandas', 'BeautifulSoup'], 'Process downloaded 10-K files and use positive, negative, and litigious word dictionaries to create document-level language measures.', 'Saved dataframe output shows filing names, word counts, and dictionary-based sentiment measures. These are word-frequency measures rather than a validated prediction of company performance.', 'The downloaded 10-K text files, the three word dictionaries, pandas, and BeautifulSoup. Update the dictionary and filing-folder paths before running.'),
    ('readability', 'Readability.ipynb', 'Readability & Forward-Looking Language', 'Text mining', 'Examining how companies communicate complexity and outlook.', ['Python', 'NLTK', 'pandas'], 'Extend the filing dataframe with sentence counts, complex-word counts, Gunning FOG readability measures, and measures of future-oriented language.', 'The notebook confirms a folder of 100 files and shows a dataframe containing sentence counts, word counts, and language measures. Small tokenization examples explore how NLTK handles phrases such as “gonna.”', 'The 10-K files, sentiment dictionaries, a CMU pronunciation dictionary, NLTK with punkt_tab data, syllables, pandas, and BeautifulSoup. Update all local paths.'),
    ('regular-expressions', 'Regular Expressions.ipynb', 'Extracting Management Discussion', 'Text mining', 'Looking beyond the full filing to the section that matters.', ['Python', 'Regex', 'pandas'], 'Extract Item 7, Management’s Discussion and Analysis, from 100 10-Ks. Compare full-document and section-level measures, and save the dataframe as a pickle file.', 'Saved output shows full-filing language statistics and exploratory regular-expression code for Item 7. The notebook includes the extraction assignment and a pickle-loading step, but does not demonstrate a completed extraction-quality evaluation.', 'The 10-K files, dictionaries, NLTK data, syllables, pandas, and BeautifulSoup. Update the paths and review section matches before interpreting the results.'),
]
esc = html.escape

def page(title, body, active='', prefix=''):
    nav = ''.join(f'<a href="{prefix}{file}"'+(' aria-current="page"' if active == label else '')+f'>{label}</a>' for label, file in [('Home','index.html?v=portfolio-2'),('About Me','about.html'),('Projects','projects.html')])
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Sarah Pajaro’s portfolio of Python, text mining, financial analysis, and machine learning projects."><title>{esc(title)} · Sarah Pajaro</title><link rel="stylesheet" href="{prefix}styles.css?v=portfolio-2"></head>
<body><a class="skip" href="#main">Skip to content</a><header class="site-header wrap"><a class="wordmark" href="{prefix}index.html?v=portfolio-2" aria-label="Sarah Pajaro home"><span class="monogram">sp.</span><span>Sarah Pajaro</span></a><nav aria-label="Main navigation">{nav}</nav></header>
<main id="main" class="wrap">{body}</main><footer class="wrap"><span>© 2026 Sarah Pajaro</span><span>Curiosity. Analysis. Discovery.</span><a href="{prefix}projects.html">Explore the work <span aria-hidden="true">↗</span></a></footer></body></html>'''

def card(p, i):
    slug, filename, title, category, desc, tags, *_ = p
    return f'''<article class="project-card"><div class="card-top"><span>{i:02d} / {category}</span><span aria-hidden="true">↗</span></div><h3>{title}</h3><p>{desc}</p><div class="tags">{''.join(f'<span>{t}</span>' for t in tags)}</div><div class="project-links"><a href="projects/{slug}/code.html">View code <span aria-hidden="true">↗</span></a><a href="projects/{slug}/index.html">Instructions &amp; outcomes <span aria-hidden="true">↗</span></a></div></article>'''

def write(name, content):
    path = ROOT / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')

write('index.html', page('Home', '''<section class="hero"><div class="hero-copy"><p class="eyebrow">PYTHON · TEXT MINING · MACHINE LEARNING</p><h1>Finding meaning<br>in the <span>details.</span></h1><p class="intro">I’m Sarah Pajaro. I explore the intersection of data and language, turning complex information into something we can understand.</p><div class="hero-actions"><a class="button" href="projects.html">Explore my projects <span aria-hidden="true">↗</span></a><a class="text-link" href="about.html">A little about me <span aria-hidden="true">→</span></a></div></div><div class="hero-art" role="img" aria-label="Abstract diagram of connections between data, language, and insight"><div class="art-label">A PRACTICE IN EXPLORATION</div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><span class="art-dot dot-one"></span><span class="art-dot dot-two"></span><span class="art-center">s<span>p</span>.</span><div class="art-bottom"><span>DATA → LANGUAGE → INSIGHT</span><span>01—07</span></div></div></section><div class="focus-strip"><span>A closer look at my work</span><span>Financial text analysis</span><span>Natural language processing</span><span>Neural networks</span></div><section class="section"><div class="section-heading"><div><p class="eyebrow">SELECTED WORK</p><h2>Questions into projects.</h2></div><a class="text-link" href="projects.html">View all 7 projects <span aria-hidden="true">↗</span></a></div><div class="project-grid">'''+''.join(card(p,i+1) for i,p in enumerate(PROJECTS[:3]))+'''</div></section><section class="closing"><p class="eyebrow">BEHIND THE WORK</p><h2>A curious mind.<br>A thoughtful approach.</h2><a class="text-link" href="about.html">Get to know me <span aria-hidden="true">↗</span></a></section>''', 'Home'))

write('about.html', page('About Me', '''<section class="page-heading"><p class="eyebrow">ABOUT ME</p><h1>Curiosity is the<br>starting point.</h1><p class="intro">I’m Sarah Pajaro. My work brings together Python, text analysis, and machine learning to explore patterns in data.</p></section><section class="about-layout"><div class="about-mark" aria-hidden="true">sp.</div><div class="about-copy"><p class="eyebrow">MY APPROACH</p><h2>From raw information<br>to a clearer picture.</h2><p>My projects follow a path from collecting information to asking what it can tell us. I work with annual reports and earnings calls, exploring how financial language can be organized, measured, and classified.</p><p>Alongside text mining, I explore machine learning through hands-on projects, including building a neural network for handwritten digit recognition. Each notebook captures the process: the code, the experiments, and the results.</p><p>This portfolio brings those projects together, with a look at both how they were built and what their saved results show.</p><div class="hero-actions"><a class="button" href="projects.html">Explore the work <span aria-hidden="true">↗</span></a><a class="text-link" href="https://www.linkedin.com/in/sarah-pajaro" target="_blank" rel="noopener noreferrer">Connect on LinkedIn <span aria-hidden="true">↗</span></a><a class="text-link" href="mailto:smp453@scarletmail.rutgers.edu">Send me an email <span aria-hidden="true">↗</span></a></div></div></section><section class="section"><p class="eyebrow">IN MY TOOLKIT</p><div class="skill-list"><div><span>01</span><h3>Collect &amp; structure</h3><p>Python, requests, BeautifulSoup, pandas</p></div><div><span>02</span><h3>Analyze &amp; interpret</h3><p>Text mining, NLTK, regular expressions, sentiment analysis</p></div><div><span>03</span><h3>Model &amp; explore</h3><p>NumPy, SciPy, Naive Bayes, neural networks, Gradio</p></div></div></section>''', 'About Me'))

write('projects.html', page('Projects', '''<section class="page-heading"><p class="eyebrow">THE PROJECT COLLECTION / 07</p><h1>Built to explore.<br>Shared to explain.</h1><p class="intro">Seven projects in data, language, and machine learning. Explore the original code, the task behind it, and the outcomes recorded along the way.</p></section><section class="section projects-section" aria-label="All projects"><div class="collection-heading"><h2>All projects <span>07</span></h2><span>PYTHON NOTEBOOKS</span></div><div class="project-grid">'''+''.join(card(p,i+1) for i,p in enumerate(PROJECTS))+'''</div></section>''', 'Projects'))

for p in PROJECTS:
    slug, filename, title, category, desc, tags, instructions, outcomes, setup = p
    notebook = json.loads((ROOT / filename).read_text(encoding='utf-8'))
    head = f'<a class="back-link" href="../../projects.html">← All projects</a><section class="detail-heading"><p class="eyebrow">{category.upper()}</p><h1>{title}</h1><p class="intro">{desc}</p></section>'
    tabs = lambda code: f'<nav class="project-tabs" aria-label="Project views"><a href="index.html"'+(' aria-current="page"' if not code else '')+'>Instructions &amp; outcomes</a><a href="code.html"'+(' aria-current="page"' if code else '')+'>Code</a></nav>'
    summary = head + tabs(False) + f'<div class="case-study"><section><p class="eyebrow">01 / THE TASK</p><h2>Instructions</h2><p>{esc(instructions)}</p></section><section><p class="eyebrow">02 / THE PROCESS</p><h2>Running the notebook</h2><p>{esc(setup)}</p><p>Open the original notebook in Jupyter or Google Colab. Review the file paths and dependencies, then run the cells in order. External datasets and Google Drive files referenced in the notebook are not included in this portfolio.</p><a class="text-link" href="../../{quote(filename)}" download>Download original notebook ↓</a></section><section><p class="eyebrow">03 / THE RESULTS</p><h2>Recorded outcomes</h2><p>{esc(outcomes)}</p><p class="muted">Summarized from the uploaded notebook and its saved outputs. Results have not been rerun for this website.</p></section></div>'
    outputs = []
    code = []
    for i,c in enumerate(notebook['cells']):
        source = ''.join(c.get('source', []))
        if c['cell_type'] == 'code' and source.strip():
            code.append(f'<section class="code-cell"><div class="cell-label">CELL {i+1:02d} · PYTHON</div><pre><code>{esc(source)}</code></pre></section>')
        for j,o in enumerate(c.get('outputs', [])):
            data = o.get('data', {})
            text = o.get('text', data.get('text/plain', []))
            text = ''.join(text) if isinstance(text,list) else str(text)
            if text.strip():
                excerpt = text[:12000]
                if len(text)>12000: excerpt += '\n\n[Long output shortened. Full output is available in the original notebook.]'
                outputs.append(f'<details><summary>Cell {i+1} · saved text output</summary><pre>{esc(excerpt)}</pre></details>')
            if 'image/png' in data:
                image = ''.join(data['image/png'])
                asset = f'output-{i}-{j}.png'
                dest = ROOT/'projects'/slug/asset
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_bytes(base64.b64decode(image))
                outputs.append(f'<figure><img loading="lazy" src="{asset}" alt="Saved plot from {esc(title)} notebook, cell {i+1}"><figcaption>Original notebook · cell {i+1}</figcaption></figure>')
    if outputs: summary += '<section class="saved-results"><h2>From the notebook</h2><p class="muted">Original saved outputs, including exploratory results.</p>'+''.join(outputs)+'</section>'
    write(f'projects/{slug}/index.html', page(title, summary, 'Projects', '../../'))
    write(f'projects/{slug}/code.html', page(title+' — Code', head+tabs(True)+f'<div class="code-intro"><p>Original Python code, in notebook order. Google Colab commands are preserved.</p><a class="text-link" href="../../{quote(filename)}" download>Download notebook ↓</a></div>'+''.join(code), 'Projects', '../../'))

print(f'Built Home, About Me, Projects, and two pages for each of {len(PROJECTS)} notebooks.')
